  5646          if(off + t1[i].len <= ctx->size) {
  5647              if(md_ascii_case_eq(STR(off), t1[i].name, t1[i].len))
  5648                  return 1;
  5649          }
  5650      }
  5651
  5652      /* Check for type 2: <!-- */
