  5690                      if(ISBLANK(tmp) || ISNEWLINE(tmp) || CH(tmp) == _T('>'))
  5691                          return 6;
  5692                      if(tmp+1 < ctx->size && CH(tmp) == _T('/') && CH(tmp+1) == _T('>'))
  5693                          return 6;
  5694                      break;
  5695                  }
  5696              }
  5697          }
  5698      }
