  5716  /* Case sensitive check whether there is a substring 'what' between 'beg'
  5717   * and end of line. */
  5718  static int
  5719  md_line_contains(MD_CTX* ctx, OFF beg, const CHAR* what, SZ what_len, OFF* p_end)
  5720  {
  5721      OFF i;
  5722      for(i = beg; i + what_len < ctx->size; i++) {
  5723          if(ISNEWLINE(i))
  5724              break;
  5725          if(memcmp(STR(i), what, what_len * sizeof(CHAR)) == 0) {
  5726              *p_end = i + what_len;
  5727              return TRUE;
  5728          }
  5729      }
  5730
  5731      *p_end = i;
  5732      return FALSE;
  5733  }
